@@ -0,0 +1,23 @@
+import Anthropic from "@anthropic-ai/sdk";
+import { pool } from "../db/pool";
+
+const client = new Anthropic();
+
+export async function summarizeChunks(docId: string, tenantId: string) {
+  const { rows } = await pool.query(
+    "SELECT id, content FROM chunks WHERE doc_id = $1 AND tenant_id = $2",
+    [docId, tenantId]
+  );
+  for (const row of rows) {
+    const msg = await client.messages.create({
+      model: "claude-opus-4",
+      max_tokens: 4096,
+      messages: [
+        { role: "user", content: `Summarize in one line:\n${row.content}` },
+      ],
+    });
+    const block = msg.content[0];
+    const summary = block.type === "text" ? block.text : "";
+    await pool.query("UPDATE chunks SET summary = $1 WHERE id = $2", [summary, row.id]);
+  }
+}
