+import type { Pool } from "pg";
+import type { Document, DocumentStore } from "../domain/documentStore";
+
+export class PgDocumentStore implements DocumentStore {
+  constructor(private readonly pool: Pool) {}
+
+  async get(tenantId: string, id: string): Promise<Document | null> {
+    const { rows } = await this.pool.query(
+      "SELECT id, tenant_id, title FROM documents WHERE tenant_id = $1 AND id = $2",
+      [tenantId, id]
+    );
+    const r = rows[0];
+    return r ? { id: r.id, tenantId: r.tenant_id, title: r.title } : null;
+  }
+
+  async save(doc: Document): Promise<void> {
+    await this.pool.query(
+      "INSERT INTO documents (id, tenant_id, title) VALUES ($1,$2,$3) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title",
+      [doc.id, doc.tenantId, doc.title]
+    );
+  }
+}
