+
+export interface TenantUsage {
+  tenantId: string;
+  total: number;
+  ready: number;
+}
+
+export async function usageByTenant(since: Date): Promise<TenantUsage[]> {
+  const { rows } = await reportingPool.query(
+    `SELECT tenant_id,
+            count(*)::int AS total,
+            count(*) FILTER (WHERE status = 'ready')::int AS ready
+       FROM report_documents_v1
+      WHERE created_at >= $1
+      GROUP BY tenant_id
+      ORDER BY total DESC`,
+    [since]
+  );
+  return rows.map((r) => ({
+    tenantId: r.tenant_id,
+    total: r.total,
+    ready: r.ready,
+  }));
+}

