@@ -0,0 +1,23 @@
+import { pool } from "../db/pool";
+import { enqueueEmbedding } from "../queues/embeddingQueue";
+
+const STALE_AFTER_DAYS = 30;
+
+export async function reindexStale(): Promise<number> {
+  const { rows } = await pool.query(
+    `UPDATE documents
+        SET status = 'pending_embedding', embedded_at = NULL
+      WHERE embedded_at < now() - ($1 || ' days')::interval
+        AND status = 'ready'
+      RETURNING id, tenant_id`,
+    [STALE_AFTER_DAYS]
+  );
+  for (const row of rows) {
+    await enqueueEmbedding({ documentId: row.id, tenantId: row.tenant_id });
+  }
+  return rows.length;
+}
+
+if (require.main === module) {
+  reindexStale().then((n) => console.log(`requeued ${n} documents`));
+}
