@@ -14,13 +14,24 @@ export type DocStatus =
   | "pending_embedding"
   | "embedding"
   | "ready"
   | "failed";

+const ALLOWED: Record<DocStatus, DocStatus[]> = {
+  uploaded: ["pending_embedding"],
+  pending_embedding: ["embedding", "failed"],
+  embedding: ["ready", "failed"],
+  ready: [],
+  failed: ["pending_embedding"],
+};
+
 export async function transition(id: string, from: DocStatus, to: DocStatus) {
+  if (!ALLOWED[from].includes(to)) {
+    throw new Error(`illegal transition ${from} -> ${to}`);
+  }
   const res = await pool.query(
     `UPDATE documents SET status = $3, updated_at = now()
       WHERE id = $1 AND status = $2`,
     [id, from, to]
   );
   if (res.rowCount === 0) throw new Error(`document ${id} not in ${from}`);
 }

